'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { EndpointDetail } from './endpoint-detail';
import { EndpointList, HEALTH_WORD, shortUrlOf } from './endpoint-list';
import {
  endpointOf,
  healthOf,
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  RETRY_MS,
  SCRIPT,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** On a phone one view shows at a time; a wide block always shows both. */
function listVisibilityOf(isDetailOpen: boolean) {
  if (isDetailOpen) {
    return 'hidden';
  }
  return 'block';
}

function detailVisibilityOf(isDetailOpen: boolean) {
  if (isDetailOpen) {
    return 'block';
  }
  return 'hidden';
}

export default function AgentOps06() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const endpoint = endpointOf(state, state.selectedId);
  const health = healthOf(state, endpoint.id);
  const announcement = `${shortUrlOf(endpoint.url)}: ${HEALTH_WORD[health]}`;
  const message = spokenUnless(isAutoplaying, announcement);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function select(id: string) {
    act({ type: 'selected', id });
    focusLater('[data-back]');
  }

  function back() {
    act({ type: 'back' });
    focusLater(`[data-endpoint="${state.selectedId}"]`);
  }

  function retry(id: string) {
    act({ type: 'retry', id });
    schedule(() => act({ type: 'retried', id }), RETRY_MS);
  }

  function openForm() {
    act({ type: 'formOpened' });
    focusLater('[data-form-first]');
  }

  function closeForm() {
    act({ type: 'formClosed' });
    focusLater('[data-add-endpoint]');
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-6xl flex-col gap-4 p-4 @3xl:p-8 @4xl:flex-row @4xl:items-start @4xl:gap-6'>
          <div
            className={cn(
              'transition-opacity duration-200 @4xl:block @4xl:w-[24rem] @4xl:shrink-0 starting:opacity-0',
              listVisibilityOf(state.isDetailOpen)
            )}
          >
            <EndpointList
              state={state}
              pressed={pressed}
              onAction={act}
              onSelect={select}
              onOpenForm={openForm}
              onCloseForm={closeForm}
            />
            <div className='flex h-9 items-end'>
              <ReplayButton
                isShown={canReplay}
                onReplay={restart}
                label='Replay the retry'
              />
            </div>
          </div>
          <div
            className={cn(
              'min-w-0 flex-1 @4xl:block',
              detailVisibilityOf(state.isDetailOpen)
            )}
          >
            <EndpointDetail
              endpoint={endpoint}
              state={state}
              pressed={pressed}
              onAction={act}
              onBack={back}
              onRetry={retry}
            />
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CheckIcon, PlusIcon } from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { CopyButton } from '@/registry/ndeko/ui/copy-button';
import { Input } from '@/registry/ndeko/ui/input';
import { Label } from '@/registry/ndeko/ui/label';
import { Toggle } from '@/registry/ndeko/ui/toggle';

import { EVENT_NAMES, type Endpoint, type EventName } from './data';
import {
  healthOf,
  hoursOf,
  totalsOf,
  type FormState,
  type Health,
  type WebhookAction,
  type WebhookState,
} from './session';

const RATE_FORMAT = new Intl.NumberFormat('en-US', {
  minimumFractionDigits: 1,
  maximumFractionDigits: 1,
});

export const HEALTH_WORD: Record<Health, string> = {
  healthy: 'Healthy',
  retrying: 'Retrying',
  failing: 'Failing',
};

/** Retrying is the one live state, so it is the one that breathes. */
export const HEALTH_DOT: Record<Health, string> = {
  healthy: 'bg-success',
  retrying: 'bg-info animate-pulse',
  failing: 'bg-destructive',
};

export function rateTextOf(rate: number) {
  return `${RATE_FORMAT.format(rate)}%`;
}

export function shortUrlOf(url: string) {
  return url.replace('https://', '');
}

function rowToneOf(isSelected: boolean) {
  if (isSelected) {
    return 'bg-foreground/[0.05]';
  }
  return 'hover:bg-foreground/[0.03]';
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.985] bg-foreground/[0.07]';
  }
  return undefined;
}

/** The arrow keys walk the rows of a list. */
export function moveBetweenRows(event: React.KeyboardEvent<HTMLElement>) {
  const isDown = event.key === 'ArrowDown';
  const isUp = event.key === 'ArrowUp';
  if (!isDown && !isUp) {
    return;
  }
  const found = event.currentTarget.querySelectorAll<HTMLElement>('[data-row]');
  const rows = Array.from(found);
  const current = rows.findIndex((row) => row === document.activeElement);
  if (current === -1) {
    return;
  }
  let next = current - 1;
  if (isDown) {
    next = current + 1;
  }
  const target = rows[next];
  if (target) {
    event.preventDefault();
    target.focus();
  }
}

type EndpointRowProps = {
  endpoint: Endpoint;
  state: WebhookState;
  isPressed: boolean;
  onSelect: (id: string) => void;
};

function EndpointRow({
  endpoint,
  state,
  isPressed,
  onSelect,
}: EndpointRowProps) {
  const health = healthOf(state, endpoint.id);
  const hours = hoursOf(state, endpoint);
  const totals = totalsOf(hours);
  const hasTraffic = totals.ok + totals.failed > 0;
  const isSelected = state.selectedId === endpoint.id;
  const shortUrl = shortUrlOf(endpoint.url);

  return (
    <button
      type='button'
      data-row
      data-endpoint={endpoint.id}
      aria-pressed={isSelected}
      onClick={() => onSelect(endpoint.id)}
      className={cn(
        'focus-visible:ring-ring/25 flex w-full cursor-pointer flex-col gap-2 rounded-lg px-2.5 py-2.5 text-start transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px] focus-visible:ring-inset',
        rowToneOf(isSelected),
        pressedQuietOf(isPressed)
      )}
    >
      <span className='flex items-center gap-2'>
        <span
          aria-hidden='true'
          className={cn(
            'size-2 shrink-0 rounded-full transition-colors duration-300',
            HEALTH_DOT[health]
          )}
        />
        <code className='min-w-0 flex-1 truncate font-mono text-xs'>
          {shortUrl}
        </code>
        <span className='sr-only'>{HEALTH_WORD[health]}</span>
        {hasTraffic && (
          <span className='text-muted-foreground shrink-0 text-xs tabular-nums'>
            {rateTextOf(totals.rate)}
          </span>
        )}
        {!hasTraffic && (
          <span className='text-muted-foreground shrink-0 text-xs'>
            No delivery yet
          </span>
        )}
      </span>
      <span className='flex flex-wrap gap-1 ps-4'>
        {endpoint.events.map((event) => (
          <Badge
            key={event}
            variant='secondary'
            className='font-mono text-[11px]'
          >
            {event}
          </Badge>
        ))}
      </span>
    </button>
  );
}

type EndpointFormProps = {
  form: FormState;
  pressed: string | null;
  onAction: (action: WebhookAction) => void;
  onClose: () => void;
};

function EndpointForm({ form, pressed, onAction, onClose }: EndpointFormProps) {
  const urlId = useId();
  const errorId = useId();
  const hasError = form.error !== null;

  function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onAction({ type: 'created' });
  }

  function toggle(event: EventName) {
    onAction({ type: 'eventToggled', event });
  }

  return (
    <form noValidate onSubmit={submit} className='flex flex-col gap-3'>
      <div className='flex flex-col gap-1.5'>
        <Label htmlFor={urlId}>Endpoint URL</Label>
        <Input
          id={urlId}
          data-form-first
          type='url'
          inputMode='url'
          autoComplete='off'
          autoCapitalize='off'
          spellCheck={false}
          placeholder='https://example.com/hooks'
          value={form.url}
          aria-invalid={hasError}
          aria-describedby={errorId}
          onChange={(event) =>
            onAction({ type: 'urlTyped', text: event.target.value })
          }
          className='font-mono'
        />
      </div>
      <div className='flex flex-col gap-1.5'>
        <span className='text-[13px] leading-none font-medium'>Events</span>
        <div role='group' aria-label='Events' className='flex flex-wrap gap-1'>
          {EVENT_NAMES.map((event) => {
            const isOn = form.events.includes(event);
            return (
              <Toggle
                key={event}
                size='sm'
                variant='outline'
                pressed={isOn}
                onPressedChange={() => toggle(event)}
                className='gap-1 rounded-full px-2.5 font-mono text-xs'
              >
                {isOn && <CheckIcon className='size-3' />}
                {event}
              </Toggle>
            );
          })}
        </div>
      </div>
      <p id={errorId} aria-live='polite' className='empty:hidden'>
        {hasError && (
          <span className='text-destructive-ink text-xs'>{form.error}</span>
        )}
      </p>
      <div className='flex items-center justify-end gap-2'>
        <Button type='button' variant='ghost' size='sm' onClick={onClose}>
          Cancel
        </Button>
        <Button
          type='submit'
          size='sm'
          className={pressedSolidOf(pressed === 'create')}
        >
          Create endpoint
        </Button>
      </div>
    </form>
  );
}

type CreatedNoticeProps = {
  secret: string;
  onDone: () => void;
};

/** The one time the secret of a new endpoint is on screen. */
function CreatedNotice({ secret, onDone }: CreatedNoticeProps) {
  return (
    <div className='flex flex-col gap-2.5 transition-opacity duration-300 starting:opacity-0'>
      <p className='flex items-center gap-1.5 text-[13px] font-medium'>
        <CheckIcon className='text-success-foreground size-4 shrink-0' />
        Endpoint created
      </p>
      <p className='text-muted-foreground text-xs'>
        Its signing secret is shown once. Copy it before you close this.
      </p>
      <div className='bg-card hairline-ring ring-foreground/12 dark:bg-foreground/[0.04] flex h-8 items-center gap-1 rounded-md ps-2.5 pe-1'>
        <code className='min-w-0 flex-1 truncate font-mono text-xs'>
          {secret}
        </code>
        <CopyButton text={secret} label='Copy the signing secret' />
      </div>
      <Button
        type='button'
        variant='outline'
        size='sm'
        onClick={onDone}
        className='self-end'
      >
        Done
      </Button>
    </div>
  );
}

export type EndpointListProps = {
  state: WebhookState;
  pressed: string | null;
  onAction: (action: WebhookAction) => void;
  onSelect: (id: string) => void;
  onOpenForm: () => void;
  onCloseForm: () => void;
};

export function EndpointList({
  state,
  pressed,
  onAction,
  onSelect,
  onOpenForm,
  onCloseForm,
}: EndpointListProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const form = state.form;
  const isFormOpen = form.phase !== 'closed';
  let createdSecret: string | null = null;
  if (form.phase === 'created') {
    createdSecret = form.secret;
  }

  return (
    <section aria-label='Endpoints' className='flex flex-col gap-3'>
      <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
        <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
          <h1 className='text-lg font-semibold text-balance'>Webhooks</h1>
          <p className='text-muted-foreground text-xs'>
            Where agent events are sent
          </p>
        </div>
        <Button
          type='button'
          size='sm'
          data-add-endpoint
          aria-expanded={isFormOpen}
          disabled={isFormOpen}
          onClick={onOpenForm}
          className={pressedSolidOf(pressed === 'add')}
        >
          <PlusIcon />
          Add endpoint
        </Button>
      </header>

      <Fold open={isFormOpen}>
        <div className='bg-foreground/[0.03] dark:bg-foreground/[0.05] rounded-xl p-3'>
          {createdSecret === null && (
            <EndpointForm
              form={form}
              pressed={pressed}
              onAction={onAction}
              onClose={onCloseForm}
            />
          )}
          {createdSecret !== null && (
            <CreatedNotice secret={createdSecret} onDone={onCloseForm} />
          )}
        </div>
      </Fold>

      <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] rounded-xl p-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <ul className='flex flex-col gap-0.5' onKeyDown={moveBetweenRows}>
          <AnimatePresence initial={false}>
            {state.endpoints.map((endpoint) => (
              <motion.li
                key={endpoint.id}
                className='overflow-hidden'
                {...rowPresence}
              >
                <EndpointRow
                  endpoint={endpoint}
                  state={state}
                  isPressed={pressed === `endpoint-${endpoint.id}`}
                  onSelect={onSelect}
                />
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      </div>
    </section>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  ArrowLeftIcon,
  CheckIcon,
  CircleCheckIcon,
  CircleXIcon,
  EyeIcon,
  EyeOffIcon,
  LoaderIcon,
} from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { CopyButton } from '@/registry/ndeko/ui/copy-button';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';

import type { Delivery, DeliveryStatus, Endpoint, HourBucket } from './data';
import { HEALTH_DOT, HEALTH_WORD, moveBetweenRows } from './endpoint-list';
import { codeVariantOf, codeWordOf, Inspector } from './inspector';
import {
  deliveriesOf,
  healthOf,
  hoursOf,
  totalsOf,
  type DayTotals,
  type WebhookAction,
  type WebhookState,
} from './session';

const RATE_FORMAT: Intl.NumberFormatOptions = {
  minimumFractionDigits: 1,
  maximumFractionDigits: 1,
};

const HEALTH_WORDS = Object.values(HEALTH_WORD);

const SECRET_PREFIX = 'whsec_';

const SHOWN_TAIL = 4;

const RETRY_STATE: Record<DeliveryStatus, MorphState> = {
  failed: 'idle',
  pending: 'busy',
  done: 'done',
};

const RETRY_LABELS: Record<MorphState, string> = {
  idle: 'Retry',
  busy: 'Retrying',
  done: 'Delivered',
};

/** whsec_ and the last four characters stay readable, so two secrets can be told apart. */
function maskedOf(secret: string) {
  const tail = secret.slice(-SHOWN_TAIL);
  return `${SECRET_PREFIX}••••••••••••${tail}`;
}

function shownSecretOf(secret: string, isShown: boolean) {
  if (isShown) {
    return secret;
  }
  return maskedOf(secret);
}

function revealLabelOf(isShown: boolean) {
  if (isShown) {
    return 'Hide the signing secret';
  }
  return 'Show the signing secret';
}

function deliveredWordOf(totals: DayTotals) {
  const total = totals.ok + totals.failed;
  if (total === 0) {
    return 'No delivery in the last 24 hours';
  }
  if (totals.failed === 0) {
    return `${total} delivered, none failed`;
  }
  return `${total} sent, ${totals.failed} failed`;
}

function maxTotalOf(hours: HourBucket[]) {
  let max = 1;
  for (const bucket of hours) {
    max = Math.max(max, bucket.ok + bucket.failed);
  }
  return max;
}

function barStyleOf(bucket: HourBucket, max: number) {
  const total = bucket.ok + bucket.failed;
  const share = Math.max(0.06, total / max);
  return { transform: `scaleY(${share})` };
}

function barToneOf(bucket: HourBucket) {
  if (bucket.failed > 0) {
    return 'bg-destructive';
  }
  return 'bg-foreground/25';
}

function rowToneOf(isOpen: boolean) {
  if (isOpen) {
    return 'bg-foreground/[0.05]';
  }
  return 'hover:bg-foreground/[0.03]';
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.985] bg-foreground/[0.07]';
  }
  return undefined;
}

function pressedButtonOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.94] bg-foreground/[0.07]';
  }
  return undefined;
}

/** A delivery shows the retry control while it fails or once it has been sent again. */
function showsRetry(delivery: Delivery) {
  const wasSentAgain = delivery.attempt > 1;
  const isSettled = delivery.status === 'done';
  return wasSentAgain || !isSettled;
}

type HourStripProps = {
  hours: HourBucket[];
  summary: string;
};

/** One bar per hour, as tall as its traffic; an hour with a failure takes the failure colour. */
function HourStrip({ hours, summary }: HourStripProps) {
  const max = maxTotalOf(hours);

  return (
    <div className='flex flex-col gap-1.5'>
      <div
        role='img'
        aria-label={`Deliveries per hour over 24 hours. ${summary}`}
        className='flex h-10 items-end gap-[3px]'
      >
        {hours.map((bucket, hour) => (
          <span
            key={hour}
            style={barStyleOf(bucket, max)}
            className={cn(
              'h-full min-w-0 flex-1 origin-bottom rounded-t-[2px] transition-[transform,background-color] duration-300 ease-(--ease-out-strong)',
              barToneOf(bucket)
            )}
          />
        ))}
      </div>
      <div
        aria-hidden='true'
        className='text-muted-foreground flex justify-between text-[11px]'
      >
        <span>24 h ago</span>
        <span>Now</span>
      </div>
    </div>
  );
}

function DeliveryMark({ status }: { status: DeliveryStatus }) {
  return (
    <Swap swapKey={status} className='size-4 shrink-0'>
      {status === 'done' && (
        <CircleCheckIcon className='text-success-foreground size-4' />
      )}
      {status === 'failed' && (
        <CircleXIcon className='text-destructive-ink size-4' />
      )}
      {status === 'pending' && (
        <LoaderIcon className='text-muted-foreground size-4 animate-spin' />
      )}
    </Swap>
  );
}

type DeliveryRowProps = {
  delivery: Delivery;
  isOpen: boolean;
  hasRetryColumn: boolean;
  pressed: string | null;
  onOpen: (id: string) => void;
  onRetry: (id: string) => void;
};

function DeliveryRow({
  delivery,
  isOpen,
  hasRetryColumn,
  pressed,
  onOpen,
  onRetry,
}: DeliveryRowProps) {
  const codeWord = codeWordOf(delivery);

  return (
    <div className='flex items-center gap-1.5'>
      <button
        type='button'
        data-row
        aria-expanded={isOpen}
        onClick={() => onOpen(delivery.id)}
        className={cn(
          'focus-visible:ring-ring/25 flex h-10 min-w-0 flex-1 cursor-pointer items-center gap-2.5 rounded-lg px-2 text-start transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px] focus-visible:ring-inset',
          rowToneOf(isOpen),
          pressedQuietOf(pressed === `delivery-${delivery.id}`)
        )}
      >
        <DeliveryMark status={delivery.status} />
        <code className='min-w-0 flex-1 truncate font-mono text-xs'>
          {delivery.event}
        </code>
        <Badge
          variant={codeVariantOf(delivery.status)}
          className='tabular-nums transition-colors duration-300'
        >
          <Swap swapKey={codeWord}>{codeWord}</Swap>
        </Badge>
        <span className='text-muted-foreground hidden w-16 shrink-0 text-end text-xs tabular-nums @sm:block'>
          {delivery.time}
        </span>
      </button>
      {hasRetryColumn && (
        <span className='flex w-[5.5rem] shrink-0 justify-end'>
          {showsRetry(delivery) && (
            <MorphButton
              type='button'
              size='sm'
              variant='outline'
              state={RETRY_STATE[delivery.status]}
              labels={RETRY_LABELS}
              onClick={() => onRetry(delivery.id)}
              className={pressedButtonOf(pressed === `retry-${delivery.id}`)}
            />
          )}
        </span>
      )}
    </div>
  );
}

type SecretRowProps = {
  endpoint: Endpoint;
  state: WebhookState;
  onAction: (action: WebhookAction) => void;
};

function SecretRow({ endpoint, state, onAction }: SecretRowProps) {
  const isShown = state.isSecretShown;
  const isAsking = state.rotate === 'asking';
  const isRotated = state.rotate === 'rotated';
  const shownSecret = shownSecretOf(endpoint.secret, isShown);

  return (
    <div className='flex flex-col gap-2'>
      <h3 className='text-muted-foreground text-xs'>Signing secret</h3>
      <div className='flex items-center gap-1'>
        <code className='bg-foreground/[0.04] dark:bg-foreground/[0.06] h-8 min-w-0 flex-1 truncate rounded-md px-2.5 font-mono text-xs leading-8'>
          {shownSecret}
        </code>
        <Button
          type='button'
          variant='ghost'
          size='icon'
          aria-pressed={isShown}
          aria-label={revealLabelOf(isShown)}
          onClick={() => onAction({ type: 'secretToggled' })}
          className='text-muted-foreground'
        >
          <Swap swapKey={String(isShown)}>
            {isShown && <EyeOffIcon />}
            {!isShown && <EyeIcon />}
          </Swap>
        </Button>
        <Button
          type='button'
          variant='outline'
          aria-expanded={isAsking}
          disabled={isRotated}
          onClick={() => onAction({ type: 'rotateAsked' })}
        >
          Rotate
        </Button>
      </div>
      <Fold open={isAsking}>
