export type DeliveryStatus = 'done' | 'failed' | 'pending';

export type Delivery = {
  id: string;
  endpointId: string;
  event: EventName;
  status: DeliveryStatus;
  /** The HTTP status the endpoint answered with; none while the delivery is on its way. */
  code: number | null;
  time: string;
  ms: number | null;
  attempt: number;
  responseBody: string;
  payload: Record<string, unknown>;
};

